function guestDashboard(){const likes=guestDemo.likes.community?13:12;return `${guestHeader('Patient workspace','Welcome, Riya','Explore a sample health workspace. Everything here is demonstration data.',`<button class="btn btn-primary" data-action="guest-add-record">＋ Add demo record</button>`)}<div class="grid grid-4"><div class="card stat-card"><div class="stat-top">Health records <span class="stat-icon">✚</span></div><div class="stat-value">${guestDemo.records.length}</div><div class="stat-caption">Sample entries in your health library</div></div><div class="card stat-card"><div class="stat-top">Reports <span class="stat-icon">▤</span></div><div class="stat-value">${guestDemo.reports.length}</div><div class="stat-caption">Reports available to explore</div></div><div class="card stat-card"><div class="stat-top">Care connections <span class="stat-icon">♡</span></div><div class="stat-value">${guestDemo.connected?1:0}</div><div class="stat-caption">Sample clinician connection</div></div><div class="card stat-card"><div class="stat-top">Unread updates <span class="stat-icon">◌</span></div><div class="stat-value">${guestDemo.notifications.filter(n=>!n.read).length}</div><div class="stat-caption">Demo notifications</div></div></div><div class="grid grid-2" style="margin-top:17px"><section class="card"><div class="section-row"><div><h3>Health at a glance</h3><p>Your sample health snapshot</p></div><span class="pill green">Demo profile</span></div><div class="list"><div class="list-row"><div class="stat-icon">♡</div><div class="list-copy"><strong>Blood group</strong><span>${esc(guestDemo.profile.bloodGroup)}</span></div></div><div class="list-row"><div class="stat-icon">◷</div><div class="list-copy"><strong>Next appointment</strong><span>${esc(guestDemo.appointments[0]?.date||'Not scheduled')} · ${esc(guestDemo.appointments[0]?.time||'')}</span></div></div><div class="list-row"><div class="stat-icon">▤</div><div class="list-copy"><strong>Latest report</strong><span>${esc(guestDemo.reports[0]?.name||'No report')}</span></div></div></div><div class="actions"><a class="btn btn-sm" href="#health">Open health records</a><a class="btn btn-sm btn-ghost" href="#reports">View reports</a></div></section><section class="card"><div class="section-row"><div><h3>Community appreciation</h3><p>Try the like interaction in this demo</p></div><span class="pill">Sample post</span></div><div class="community-demo"><div class="avatar">DR</div><div><strong>Dr. Aanya Mehta</strong><p class="muted">“Small, consistent health habits can make it easier to notice changes over time.”</p></div></div><button class="btn ${guestDemo.likes.community?'btn-primary':'btn-ghost'}" data-action="guest-like" data-id="community">${guestDemo.likes.community?'♥ Liked':'♡ Like'} · ${likes}</button><p class="tiny muted" style="margin:10px 0 0">Likes in guest mode are only simulated in this browser session.</p></section></div><section class="card" style="margin-top:17px"><div class="section-row"><div><h3>Explore every workspace</h3><p>Open all patient, clinician and administration demo screens from the navigation.</p></div><span class="pill">11 modules</span></div><div class="guest-quick-links"><a href="#profile">My profile →</a><a href="#assistant">AI health guide →</a><a href="#appointments">Appointments →</a><a href="#patients">Clinician workspace →</a><a href="#admin">Admin review →</a></div></section>`;}
function guestProfilePage(){const p=guestDemo.profile||{},completion=profileCompletion(p);const toggle=(title,description,name,value)=>`<label class="profile-toggle"><span class="profile-toggle-copy"><strong>${title}</strong><small>${description}</small></span><input class="switch" type="checkbox" name="${name}" ${value?'checked':''}></label>`;return `${guestHeader('Personal health identity','Your profile, your story','Explore the same detailed profile workspace using temporary sample data.') }<form id="guest-profile-form" class="profile-form"><section class="profile-hero card"><div class="profile-cover-area"><div class="profile-cover-wash"></div><img class="profile-hero-art" src="/assets/profile-consultation.webp" alt="Illustration of a patient talking with a clinician"><div class="profile-cover-copy"><span class="profile-overline">GUEST MEMBER SPACE</span><strong>Your health story, thoughtfully organised.</strong><small>Personal details · Care connections · Privacy</small></div></div><div class="profile-hero-bottom"><div class="profile-avatar-wrap"><div class="profile-avatar-large">${initials(p.displayName)}</div></div><div class="profile-identity"><div class="profile-name-line"><h2>${esc(p.displayName||'Guest member')}</h2><span class="pending-chip">Demo profile</span></div><p>Temporary sample account · Patient workspace</p><div class="profile-identity-tags"><span>@${esc(p.username||'username')}</span><span>${esc([p.city,p.country].filter(Boolean).join(', ')||'Location not added')}</span></div></div><div class="profile-completion-box">${progressRing(completion)}<div><strong>${completion}% complete</strong><small>Profile strength</small><div class="progress profile-progress-bar"><span style="width:${completion}%"></span></div></div></div></div></section><div class="profile-layout"><div class="profile-main-column"><section class="card profile-section"><div class="profile-section-heading"><span class="profile-section-icon teal">✧</span><div><h3>Personal identity</h3><p>Make your profile recognisable and introduce yourself.</p></div></div><div class="form-grid">${field('Full name','displayName',p.displayName)}${field('Username','username',p.username)}${field('Pronouns','pronouns',p.pronouns||'')}${field('Occupation','occupation',p.occupation||'')}${textareaField('About you','bio',p.bio||'','A short introduction…')}</div></section><section class="card profile-section"><div class="profile-section-heading"><span class="profile-section-icon blue">◎</span><div><h3>Personal details</h3><p>Optional information for a more complete health profile.</p></div></div><div class="form-grid">${field('Date of birth','dateOfBirth',p.dateOfBirth||'','date')}${selectField('Gender','gender',p.gender||'',[['','Prefer not to say'],['female','Female'],['male','Male'],['non-binary','Non-binary']])}${field('Phone','phone',p.phone||'','tel')}${field('Country code','phoneCountryCode',p.phoneCountryCode||'','text','placeholder="e.g. +91"')}${selectField('Preferred language','preferredLanguage',p.preferredLanguage||'',[['','Select a language'],['English','English'],['Hindi','Hindi'],['Bengali','Bengali'],['Punjabi','Punjabi']])}${field('Blood group','bloodGroup',p.bloodGroup||'')}${field('Height (cm)','height_cm',p.height_cm??'','number','min=30 max=260 step=0.1')}${field('Weight (kg)','weight_kg',p.weight_kg??'','number','min=1 max=500 step=0.1')}</div></section><section class="card profile-section"><div class="profile-section-heading"><span class="profile-section-icon violet">⌖</span><div><h3>Location and emergency contact</h3><p>Keep helpful information available in your private profile.</p></div></div><div class="form-grid">${field('City','city',p.city||'')}${field('State','state',p.state||'')}${field('Country','country',p.country||'')}${field('Emergency contact','emergencyContactName',p.emergencyContactName||'')}${field('Relationship','emergencyContactRelation',p.emergencyContactRelation||'')}${field('Emergency phone','emergencyContactPhone',p.emergencyContactPhone||'','tel')}</div></section></div><aside class="profile-side-column"><section class="card profile-strength-card"><div class="profile-side-title"><div><span class="profile-overline">PROFILE CHECKLIST</span><h3>Build your profile</h3></div><span class="profile-check-count">${Math.round(completion)}%</span></div><div class="profile-strength-footer"><img src="/assets/profile-care.svg" alt="Care connection illustration"><p>Complete your profile to make your health space more useful.</p></div></section><section class="card profile-privacy-card"><div class="profile-privacy-art"><img src="/assets/profile-privacy.svg" alt="Privacy illustration"></div><span class="profile-overline">YOUR DATA, YOUR CHOICE</span><h3>Privacy and sharing</h3><p class="profile-card-copy">Try the privacy controls. These changes stay only in this demo session.</p>${selectField('Profile visibility','profileVisibility',p.profileVisibility||'private',[['private','Private — only you'],['public','Public basic profile']])}${selectField('Phone visibility','phoneVisibility',p.phoneVisibility||'private',[['private','Private'],['care-team','Care team']])}<div class="profile-switches">${toggle('Share health records','Only with approved clinicians.','shareWithDoctors',p.shareWithDoctors)}${toggle('Read receipts','Show when sample messages are read.','readReceipts',p.readReceipts!==false)}</div><div class="profile-inline-note">Guest edits are temporary and never change a real account or medical record.</div></section><section class="card profile-message-card"><div class="profile-section-icon violet">✉</div><h3>Messages and discovery</h3><p class="profile-card-copy">Control who can begin a conversation in the demo.</p>${selectField('Who can message me','allowMessagesFrom',p.allowMessagesFrom||'care-team',[['care-team','Approved care connections'],['nobody','Nobody']])}</section></aside></div><div class="profile-savebar"><div><strong>Guest changes are temporary</strong><small>Sample data resets when you leave the demo.</small></div><div class="profile-actions"><button class="btn btn-primary btn-xl" type="submit">Save demo profile →</button></div></div></form>`;}
function guestHealthPage(){return `${guestHeader('Your health library','Health records','Sample history, allergies, medication and symptom entries. Use Add demo record to try adding an item.',`<button class="btn btn-primary" data-action="guest-add-record">＋ Add demo record</button>`)}<div class="notice warn">These are fictional sample entries, not medical advice or a real patient record.</div><div class="grid grid-2" style="margin-top:16px">${guestDemo.records.map(r=>`<section class="card"><div class="section-row"><span class="pill">${esc(r.kind)}</span><span class="tiny muted">${esc(r.date)}</span></div><h3>${esc(r.name)}</h3><p class="muted">${esc(r.detail)}</p><button class="btn btn-sm btn-ghost" data-action="guest-record-detail" data-id="${esc(r.id)}">View details</button></section>`).join('')}</div>`;}
function guestReportsPage(){return `${guestHeader('Reports and trends','Reports','Explore how report cards, summaries and trends are presented.') }<div class="grid grid-2">${guestDemo.reports.map(r=>`<section class="card"><div class="section-row"><span class="pill green">${esc(r.status)}</span><span class="tiny muted">${esc(r.date)}</span></div><h3>${esc(r.name)}</h3><p class="muted">${esc(r.summary)}</p><button class="btn btn-sm" data-action="guest-report-open" data-id="${esc(r.id)}">Open report summary</button></section>`).join('')}<section class="card"><h3>Sample wellness trend</h3><p class="muted">Illustrative values only — not taken from a real patient.</p><div class="trend-row"><span>Sleep</span><div class="trend-track"><i style="width:78%"></i></div><strong>7.8 h</strong></div><div class="trend-row"><span>Activity</span><div class="trend-track"><i style="width:64%"></i></div><strong>6.4 k</strong></div><div class="trend-row"><span>Hydration</span><div class="trend-track"><i style="width:84%"></i></div><strong>2.1 L</strong></div></section></div>`;}
function guestAssistantPage(){return `${guestHeader('AI health guide','Ask MedMemory AI','Try the conversation UI with sample, general wellness prompts. Responses are scripted for this demo.') }<div class="grid grid-2"><section class="card"><h3>Sample conversation</h3><div class="ai-thread" id="guest-ai-thread">${guestDemo.aiMessages.map(m=>`<div class="ai-bubble ${m.who==='user'?'user':''}"><b>${m.who==='user'?'You':'MedMemory AI'}</b><p>${esc(m.text)}</p></div>`).join('')}</div><form id="guest-ai-form" class="chat-compose"><textarea class="textarea" name="message" rows="2" placeholder="Ask a general health question…" required maxlength="1000"></textarea><button class="btn btn-primary" type="submit">Ask →</button></form></section><section class="card"><h3>Try these prompts</h3><div class="list"><button class="guest-prompt" data-action="guest-prompt" data-prompt="How can I prepare for a routine doctor visit?">How can I prepare for a routine doctor visit?</button><button class="guest-prompt" data-action="guest-prompt" data-prompt="What information should a health timeline contain?">What information should a health timeline contain?</button><button class="guest-prompt" data-action="guest-prompt" data-prompt="How do I keep track of my medicines?">How do I keep track of my medicines?</button></div><div class="notice warn" style="margin-top:15px">The sample assistant does not diagnose, prescribe or analyse real records. For urgent symptoms, contact local emergency services or a qualified clinician.</div></section></div>`;}
function guestAppointmentsPage(){return `${guestHeader('Care schedule','Appointments','Request a sample appointment and explore status tracking.',`<button class="btn btn-primary" data-action="guest-book">＋ Request demo appointment</button>`)}<div class="grid grid-2"><section class="card"><h3>Available clinicians</h3><div class="list-row"><div class="avatar">AM</div><div class="list-copy"><strong>Dr. Aanya Mehta</strong><span>General medicine · Sample clinician</span></div><button class="btn btn-sm" data-action="guest-book">Request visit</button></div><div class="list-row"><div class="avatar">SK</div><div class="list-copy"><strong>Dr. Sameer Khanna</strong><span>Cardiology · Sample clinician</span></div><button class="btn btn-sm" data-action="guest-book">Request visit</button></div></section><section class="card"><h3>Your appointment list</h3>${guestDemo.appointments.map(a=>`<div class="list-row"><div class="stat-icon">▦</div><div class="list-copy"><strong>${esc(a.title)}</strong><span>${esc(a.doctor)} · ${esc(a.date)} · ${esc(a.time)}</span></div><span class="pill green">${esc(a.status)}</span></div>`).join('')}</section></div>`;}
function guestCarePage(){return `${guestHeader('Your care team','Care connections','See how patient-clinician connections are requested and managed.') }<div class="grid grid-2"><section class="card"><div class="list-row"><div class="avatar">AM</div><div class="list-copy"><strong>Dr. Aanya Mehta</strong><span>General medicine · Sample profile</span></div><span class="pill">Clinician</span></div><p class="muted">Connect to share relevant health records and coordinate care in the real account experience.</p><button class="btn ${guestDemo.connected?'btn-ghost':'btn-primary'}" data-action="guest-connect">${guestDemo.connected?'✓ Demo connection requested':'Request demo connection'}</button></section><section class="card"><h3>How sharing works</h3><p class="muted">In a real account, you approve a care request and control whether health records are shared. Guest mode only previews the workflow.</p><div class="notice">No clinician or patient can access your actual information from this demo.</div></section></div>`;}
function guestMessagesPage(){return `${guestHeader('Secure conversations','Messages','Try a sample patient-clinician conversation. Messages stay in this temporary demo.') }<section class="card guest-chat-card"><div class="chat-head"><div class="avatar">AM</div><div><strong>Dr. Aanya Mehta</strong><div class="tiny muted">Sample care connection · Demo only</div></div><span class="pill">Online demo</span></div><div class="chat-messages" id="guest-chat-thread">${guestDemo.messages.map(m=>`<div class="message ${m.who==='you'?'mine':''}"><p>${esc(m.text)}</p><div class="message-meta">${esc(m.time)}</div>${m.who==='doctor'?`<button class="inline-link" data-action="guest-like" data-id="msg-${m.text.length}">${guestDemo.likes['msg-'+m.text.length]?'♥ Liked':'♡ Like'}</button>`:''}</div>`).join('')}</div><form id="guest-message-form" class="chat-compose"><textarea class="textarea" name="message" rows="1" maxlength="500" placeholder="Write a demo message…" required></textarea><button class="btn btn-primary" type="submit">Send</button></form></section>`;}
function guestNotificationsPage(){return `${guestHeader('Updates','Notifications','Sample reminders and activity from your demo health space.',`<button class="btn btn-sm btn-ghost" data-action="guest-mark-read">Mark all read</button>`)}<section class="card">${guestDemo.notifications.map(n=>`<div class="list-row ${n.read?'':'unread'}"><div class="stat-icon">◌</div><div class="list-copy"><strong>${esc(n.title)}</strong><span>${esc(n.detail)}</span></div>${n.read?'<span class="pill">Read</span>':'<button class="btn btn-sm" data-action="guest-read" data-id="'+esc(n.id)+'">Mark read</button>'}</div>`).join('')}</section>`;}
function guestPatientsPage(){return `${guestHeader('Clinician workspace','My patients','Guest view can open the clinician-side sample workspace too. This screen never exposes real patients.') }<div class="notice">Clinician-only workflows are shown with fictional sample patients. Real access requires an approved clinician account.</div><section class="card" style="margin-top:16px"><h3>Sample patient directory</h3>${guestDemo.patients.map(p=>`<div class="list-row"><div class="avatar">${initials(p.name)}</div><div class="list-copy"><strong>${esc(p.name)}</strong><span>${esc(p.detail)}</span></div><button class="btn btn-sm btn-primary" data-action="guest-patient-open" data-id="${esc(p.id)}">Open overview</button></div>`).join('')}</section>`;}
function guestAdminPage(){return `${guestHeader('Administration','Admin review','Preview staff-side review controls with fictional applications.') }<div class="notice warn">Guest mode is read-only for real administration. Approve/reject controls below only simulate a decision in this session.</div><section class="card" style="margin-top:16px"><h3>Sample review queue</h3>${guestDemo.adminItems.map(p=>`<div class="list-row"><div class="avatar">${initials(p.name)}</div><div class="list-copy"><strong>${esc(p.name)}</strong><span>${esc(p.detail)}</span></div><button class="btn btn-sm" data-action="guest-admin-decision" data-id="${esc(p.id)}" data-result="approved">Approve demo</button><button class="btn btn-sm btn-danger" data-action="guest-admin-decision" data-id="${esc(p.id)}" data-result="rejected">Reject demo</button></div>`).join('')}</section>`;}
function guestSettingsPage(){return `${guestHeader('Preferences','Settings','Try appearance and accessibility controls in the temporary demo.') }<section class="card"><div class="setting-row"><div><strong>Color theme</strong><span>Switch between the midnight teal and cloud light palette.</span></div><button class="btn btn-sm" data-action="toggle-theme">Switch theme</button></div><div class="setting-row"><div><strong>Current theme</strong><span>${document.documentElement.dataset.theme==='light'?'Cloud light':'Midnight teal'}</span></div><span class="pill">Active</span></div><div class="setting-row"><div><strong>Demo data</strong><span>All changes are temporary and are reset when you exit or refresh.</span></div><span class="pill green">Sandbox</span></div><div class="notice">Sign in to save real preferences and use your private health workspace.</div></section>`;}
function guestSearchPage(){const q=(searchTerm||'').toLowerCase();const items=[...guestDemo.records.map(x=>({title:x.name,detail:x.detail,href:'#health'})),...guestDemo.reports.map(x=>({title:x.name,detail:x.summary,href:'#reports'})),...guestDemo.patients.map(x=>({title:x.name,detail:x.detail,href:'#patients'}))].filter(x=>(x.title+' '+x.detail).toLowerCase().includes(q));return `${guestHeader('Workspace search','Search results',`Showing sample results for “${esc(searchTerm)}”.`)}<section class="card">${items.length?items.map(x=>`<div class="list-row"><div class="list-copy"><strong>${esc(x.title)}</strong><span>${esc(x.detail)}</span></div><a class="btn btn-sm" href="${x.href}">Open</a></div>`).join(''):empty('No sample results','Try a different search term.')}</section>`;}
function guestPage(){const p=route();if(p==='profile')return guestProfilePage();if(p==='health')return guestHealthPage();if(p==='reports')return guestReportsPage();if(p==='assistant')return guestAssistantPage();if(p==='appointments')return guestAppointmentsPage();if(p==='care')return guestCarePage();if(p==='messages')return guestMessagesPage();if(p==='notifications')return guestNotificationsPage();if(p==='patients')return guestPatientsPage();if(p==='admin')return guestAdminPage();if(p==='settings')return guestSettingsPage();if(p==='search')return guestSearchPage();return guestDashboard();}
function renderGuest(){if(!guestMode||!guestDemo)return;applyTheme(prefs.theme||localStorage.getItem('mm-theme')||'dark');const links=[['dashboard','Overview','home'],['profile','My profile','profile'],['health','Health records','health'],['reports','Reports & trends','reports'],['assistant','AI health guide','assistant'],['appointments','Appointments','appointments'],['care','Care connections','care'],['messages','Messages','messages'],['notifications','Notifications','notifications'],['patients','Clinician workspace','patients'],['admin','Admin review','settings'],['settings','Settings','settings']];const name=guestDemo.profile.displayName||'Guest';appRoot.innerHTML=`<div class="app-shell guest-shell"><aside class="sidebar"><a class="brand" href="#dashboard"><div class="brand-mark">M<span>+</span></div><div><div class="brand-name">MedMemory <em>AI</em></div><div class="brand-caption">Your health, remembered</div></div></a><div class="nav-label">Demo workspace</div><nav class="nav-list guest-nav">${links.map(([p,l,i])=>guestNavLink(p,l,i)).join('')}</nav><div class="sidebar-bottom"><div class="security-note"><strong>✦ Sample data only</strong><p>Guest actions stay in this browser session and never change real accounts.</p></div><div class="user-mini"><div class="avatar">${initials(name)}</div><div><div class="user-mini-name">${esc(name)}</div><div class="user-mini-role">Guest · Demo mode</div></div><button class="logout-small" data-action="guest-exit" title="Exit demo">↗</button></div><button class="logout-wide" data-action="guest-exit"><span>↪</span> Exit guest demo</button></div></aside><section class="main-column"><header class="topbar"><div class="mobile-brand"><div class="brand-mark">M<span>+</span></div>MedMemory</div><div class="search-wrap"><span>⌕</span><input class="input" id="global-search" placeholder="Search sample records or patients…" value="${esc(searchTerm)}"></div><div class="topbar-right"><span class="pill guest-top-pill">Guest demo</span><button class="icon-btn" data-action="toggle-theme" title="Switch light or dark mode">◐</button><button class="icon-btn" data-action="guest-exit" title="Exit demo">↗</button></div></header><main class="page" id="page">${guestDemoBanner()}${guestPage()}</main></section></div>`;}
function handleGuestAction(actionEl){const a=actionEl.dataset.action,id=actionEl.dataset.id;if(a==='close-modal'){closeModal();return;}if(a==='guest-exit'){guestMode=false;guestDemo=null;me=null;role='patient';searchTerm='';location.hash='#';authView('login');return;}if(a==='guest-like'){guestDemo.likes[id]=!guestDemo.likes[id];renderGuest();toast(guestDemo.likes[id]?'You liked this demo item.':'Like removed from this demo item.');return;}if(a==='guest-add-record'){guestDemo.records.unshift({id:'r'+Date.now(),kind:'Wellness note',name:'New demo health note',detail:'Added during the interactive guest tour.',date:new Date().toLocaleDateString()});renderGuest();toast('Sample record added to this demo session.');return;}if(a==='guest-record-detail'){const r=guestDemo.records.find(x=>x.id===id);if(r)modal(esc(r.name),esc(r.kind),`<p>${esc(r.detail)}</p><p class="tiny muted">${esc(r.date)} · Fictional sample record</p>`,`<button class="btn btn-primary" data-action="close-modal">Close</button>`);return;}if(a==='guest-report-open'){const r=guestDemo.reports.find(x=>x.id===id);if(r)modal(esc(r.name),'Sample report summary',`<div class="notice">${esc(r.summary)}</div><p class="tiny muted">This is fictional demonstration content and should not be used for health decisions.</p>`,`<button class="btn btn-primary" data-action="close-modal">Done</button>`);return;}if(a==='guest-book'){guestDemo.appointments.unshift({id:'a'+Date.now(),title:'Demo consultation request',doctor:'Dr. Aanya Mehta',date:'02 Dec 2026',time:'10:00 AM',status:'Request sent'});renderGuest();toast('Demo appointment request added.');return;}if(a==='guest-connect'){guestDemo.connected=!guestDemo.connected;renderGuest();toast(guestDemo.connected?'Demo connection request sent.':'Demo connection request withdrawn.');return;}if(a==='guest-mark-read'){guestDemo.notifications.forEach(n=>n.read=true);renderGuest();toast('Demo notifications marked as read.');return;}if(a==='guest-read'){const n=guestDemo.notifications.find(x=>x.id===id);if(n)n.read=true;renderGuest();return;}if(a==='guest-prompt'){const f=$('#guest-ai-form');if(f){f.elements.message.value=actionEl.dataset.prompt||'';f.requestSubmit();}return;}if(a==='guest-patient-open'){const p=guestDemo.patients.find(x=>x.id===id);if(p)modal(esc(p.name),'Sample patient overview',`<p>${esc(p.detail)}</p><div class="notice">This is fictional patient data. Real patient records require verified clinician access and patient permission.</div>`,`<button class="btn btn-primary" data-action="close-modal">Close</button>`);return;}if(a==='guest-admin-decision'){const item=guestDemo.adminItems.find(x=>x.id===id);if(item){item.detail=`Demo decision recorded: ${actionEl.dataset.result}. No real account was changed.`;renderGuest();toast('Demo decision recorded locally.');}return;}}
function guestAiReply(message){const q=message.toLowerCase();if(q.includes('visit')||q.includes('doctor'))return 'For a routine visit, consider bringing your current medicine list, relevant reports, allergies, previous diagnoses, and a short timeline of symptoms. Write down your questions before the appointment. This is general preparation guidance, not a diagnosis.';if(q.includes('timeline')||q.includes('record'))return 'A useful health timeline can include the date, what happened, symptoms, medicines or treatments, relevant test results, and the clinician who reviewed it. Keep entries factual and correct mistakes when you notice them.';if(q.includes('medicine')||q.includes('medication'))return 'Keep an up-to-date list of each medicine, its prescribed dose, when you take it, and who prescribed it. Do not start, stop, or change a medicine based on this sample response; confirm changes with a clinician or pharmacist.';return 'Thanks for trying the MedMemory AI demo. In a real account, the assistant can help organise health information and explain medical terms. This sample response is not a diagnosis or a substitute for professional care.';}
function submitGuestForm(form){if(form.id==='guest-profile-form'){const data=Object.fromEntries(new FormData(form));for(const name of ['shareWithDoctors','readReceipts'])data[name]=!!form.elements[name]?.checked;guestDemo.profile={...guestDemo.profile,...data};me=guestDemo.profile;renderGuest();toast('Demo profile updated for this session.');return true;}if(form.id==='guest-ai-form'){const message=form.elements.message.value.trim();if(!message)return true;guestDemo.aiMessages.push({who:'user',text:message},{who:'ai',text:guestAiReply(message)});renderGuest();const thread=$('#guest-ai-thread');if(thread)thread.scrollTop=thread.scrollHeight;return true;}if(form.id==='guest-message-form'){const message=form.elements.message.value.trim();if(!message)return true;guestDemo.messages.push({who:'you',text:message,time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})});renderGuest();const thread=$('#guest-chat-thread');if(thread)thread.scrollTop=thread.scrollHeight;toast('Demo message sent locally.');return true;}return false;}

// One delegated event layer keeps the interface lightweight and avoids duplicate listeners after navigation.
document.addEventListener('click',async e=>{
 const actionEl=e.target.closest('[data-action]');if(!actionEl)return;const a=actionEl.dataset.action;
 try{
  if(a==='start-guest'){startGuestDemo();return;}
  if(a==='google-login'){await signInGoogle();return;}
  if(a==='toggle-theme'){await toggleTheme();return;}
  if(guestMode){handleGuestAction(actionEl);return;}
  if(a==='auth-toggle')authView(actionEl.dataset.mode);
  else if(a==='close-modal')closeModal();
  else if(a==='go-profile')location.hash='#profile';else if(a==='go-health')location.hash='#health';else if(a==='go-care')location.hash='#care';else if(a==='go-appointments')location.hash='#appointments';else if(a==='go-patients')location.hash='#patients';
  else if(a==='open-profile')location.hash='#profile';else if(a==='open-settings')location.hash='#settings';else if(a==='quick-notifications')location.hash='#notifications';
  else if(a==='signout')await signOut(auth);
  else if(a==='open-record')recordModal(actionEl.dataset.kind||'medicalHistory');
  else if(a==='save-record'){const f=$('#record-form');if(!f)throw new Error('The record form is not open.');await saveRecord(actionEl.dataset.kind,f);}
  else if(a==='delete-record'){if(confirm('Remove this health record?')){await deleteDoc(doc(db,'profiles',currentUser.uid,actionEl.dataset.kind,actionEl.dataset.id));toast('Record removed.');await refresh();}}
  else if(a==='preview-profile'){const p=me||{};modal('Profile preview','A preview of basic profile details only. Medical records and private contact information are not shown.',`<div class="profile-preview-card"><div class="profile-preview-cover"><img src="${esc(p.coverUrl||'/assets/profile-consultation.webp')}" alt=""></div><div class="profile-preview-identity"><div class="profile-avatar-large">${p.avatarUrl?`<img src="${esc(p.avatarUrl)}" alt="Profile photo">`:`<span>${initials(p.displayName)}</span>`}</div><div><h2>${esc(p.displayName||'Your name')}</h2><p>@${esc(p.username||'username')} · ${esc([p.city,p.country].filter(Boolean).join(', ')||'Location not added')}</p></div></div><p>${esc(p.bio||'No introduction added yet.')}</p><div class="grid grid-2"><div><span class="tiny muted">Profession</span><p>${esc(p.occupation||p.specialty||'Not added')}</p></div><div><span class="tiny muted">Languages</span><p>${esc(p.languages||p.preferredLanguage||'Not added')}</p></div></div><div class="notice">Visibility: ${esc(p.profileVisibility||'private')}. Medical records, emergency contacts and account email remain separate from this basic profile.</div></div>`,`<button class="btn btn-primary" data-action="close-modal">Close preview</button>`);}
  else if(a==='copy-profile'){if(me?.profileVisibility!=='public')throw new Error('Set Profile visibility to Public before sharing your profile link.');await navigator.clipboard.writeText(`${location.origin}/#public-profile/${currentUser.uid}`);toast('Public profile link copied.');}
  else if(a==='verify-email')await verifyEmail();
  else if(a==='upload-report'){location.hash='#reports';setTimeout(()=>$('#report-form input[type=file]')?.click(),100);}
  else if(a==='medicine-check')await openMedicineCheck();
  else if(a==='run-medicine-check')await runMedicineCheck($('#medicine-form'));
  else if(a==='appointment-modal')location.hash='#appointments';
  else if(a==='book-doctor')await bookDoctor(actionEl.dataset.uid);
  else if(a==='request-care')await requestCare(actionEl.dataset.uid);
  else if(a==='submit-appointment')await submitAppointment($('#appointment-form'));
  else if(a==='accept-care')await acceptCare(actionEl.dataset.id);
  else if(a==='reject-care')await changeCareRequest(actionEl.dataset.id,'rejected');
  else if(a==='remove-care')await removeCare(actionEl.dataset.id);
  else if(a==='new-chat')await newChatModal();
  else if(a==='create-chat')await createChat($('#new-chat-form'));
  else if(a==='select-chat'){activeChat=actionEl.dataset.id;location.hash=`#messages/${activeChat}`;}
  else if(a==='chat-back'){const list=$('.chat-list'),panel=$('.chat-panel');list?.classList.add('mobile-visible');panel?.classList.add('mobile-hidden');}
  else if(a==='delete-message'){if(confirm('Delete this message?'))await deleteDoc(doc(db,'conversations',activeChat,'messages',actionEl.dataset.id));}
  else if(a==='edit-message'){const ref=doc(db,'conversations',activeChat,'messages',actionEl.dataset.id),snap=await getDoc(ref);if(snap.exists()){const next=prompt('Edit your message:',snap.data().text||'');if(next!==null)await updateDoc(ref,{text:next.slice(0,3000)});}}
  else if(a==='react-message'){await updateDoc(doc(db,'conversations',activeChat,'messages',actionEl.dataset.id),{likes:arrayUnion(currentUser.uid)});}
  else if(a==='read-notification'){await updateDoc(doc(db,'notifications',currentUser.uid,'items',actionEl.dataset.id),{read:true});await refresh();}
  else if(a==='mark-all-read'){const snap=await getDocs(query(collection(db,'notifications',currentUser.uid,'items'),where('read','==',false),limit(100)));const batch=writeBatch(db);snap.docs.forEach(d=>batch.update(d.ref,{read:true}));await batch.commit();toast('All notifications marked as read.');await refresh();}
  else if(a==='setting-tab'){activeSetting=actionEl.dataset.tab;await refresh();}
  else if(a==='save-settings')await saveSettings();
  else if(a==='change-password')await changePassword();
  else if(a==='revoke-sessions')await revokeSessions();
  else if(a==='delete-account')await deleteAccount();
  else if(a==='export-data')await exportData();
  else if(a==='open-file')await openStoredFile(actionEl.dataset.id);
  else if(a==='agent37')await agent37();
  else if(a==='agent37-new-chat')await newAgent37Chat();
  else if(a==='open-agent37-external'){window.open(config.agent37?.instanceUrl,'_blank','noopener,noreferrer');closeModal();}
  else if(a==='patient-detail')await patientDetail(actionEl.dataset.uid);
  else if(a==='start-consultation')await startConsultation(actionEl.dataset.uid);
  else if(a==='doctor-brief')await doctorBrief(actionEl.dataset.uid);
  else if(a==='consult-summary')consultationModal(actionEl.dataset.uid);
  else if(a==='generate-consult-summary')await generateConsultSummary($('#consult-form'));
  else if(a==='submit-doctor-application')await submitDoctorApplication($('#doctor-application-form'));
  else if(a==='apply-doctor')applyDoctorModal();
  else if(a==='approve-doctor'){if(confirm('Approve this clinician account after verifying credentials?')){await api(`/admin/doctors/${encodeURIComponent(actionEl.dataset.uid)}/approve`,{method:'POST',body:{}});toast('Clinician approved. They must sign in again to refresh permissions.');await refresh();}}
  else if(a==='reject-doctor'){const note=prompt('Optional reason for rejecting this application:')||'';await api(`/admin/doctors/${encodeURIComponent(actionEl.dataset.uid)}/reject`,{method:'POST',body:{note}});toast('Application rejected.');await refresh();}
  else if(a==='appointment-status'){const ref=doc(db,'appointments',actionEl.dataset.id),snap=await getDoc(ref);await updateDoc(ref,{status:actionEl.dataset.status,updatedAt:serverTimestamp()});if(snap.exists())api('/notifications',{method:'POST',body:{type:'appointment-update',targetUid:snap.data().patientUid,appointmentId:snap.id,title:actionEl.dataset.status==='booked'?'Appointment confirmed':'Appointment declined',body:`Your clinician ${actionEl.dataset.status==='booked'?'confirmed':'declined'} the appointment request.`}}).catch(()=>{});toast('Appointment status updated.');await refresh();}
  else if(a==='forgot-password'){const email=prompt('Enter the email address for your account:');if(email){await sendPasswordResetEmail(auth,email);toast('Password reset email sent if the account exists.');}}
 }catch(err){console.error(err);toast(err.message||'Something went wrong.','error');}
});
document.addEventListener('change',e=>{
 const input=e.target.closest('[data-profile-image]');if(!input)return;
 const file=input.files?.[0];if(!file)return;
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Choose a JPG, PNG or WebP image.','error');input.value='';return;}
 if(file.size>10*1024*1024){toast('Choose an image smaller than 10 MB.','error');input.value='';return;}
 const reader=new FileReader();reader.onload=()=>{
  const target=input.dataset.profileImage==='avatar'?$('#profile-avatar-preview'):$('#profile-cover-preview');if(!target)return;
  const img=document.createElement('img');img.src=String(reader.result||'');img.alt=input.dataset.profileImage==='avatar'?'Selected profile photo':'Selected profile cover';
  if(input.dataset.profileImage==='avatar'){img.className='profile-avatar-photo';target.replaceChildren(img);}
  else {img.className='profile-cover-photo';target.querySelector('.profile-cover-photo')?.remove();target.prepend(img);}
 };
 reader.readAsDataURL(file);
});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('form'))return;e.preventDefault();try{
 if(guestMode&&submitGuestForm(form))return;
 if(form.id==='agent37-chat-form')await sendAgent37Message(form);
 else if(form.id==='auth-form'){const submit=$('button[type=submit]',form);submit.disabled=true;try{await submitAuth(form);}finally{submit.disabled=false;}}
 else if(form.id==='profile-form')await submitProfile(form);
 else if(form.id==='record-form')await saveRecord(form.dataset.kind,form);
 else if(form.id==='report-form')await submitReport(form);
 else if(form.id==='ai-form')await sendAI(form);
 else if(form.id==='message-form')await sendMessage(form);
 else if(form.id==='new-chat-form')await createChat(form);
 else if(form.id==='appointment-form')await submitAppointment(form);
 else if(form.id==='consult-form')await generateConsultSummary(form);
 else if(form.id==='doctor-application-form')await submitDoctorApplication(form);
 else if(form.id==='medicine-form')await runMedicineCheck(form);
 }catch(err){console.error(err);toast(err.message||'Could not complete that action.','error');}
});
document.addEventListener('change',e=>{if(e.target.id==='agent37-consent'){const button=$('.agent37-send');if(button&&!agent37Busy)button.disabled=!e.target.checked;}});
document.addEventListener('keydown',async e=>{if(e.target.id==='global-search'&&e.key==='Enter'){searchTerm=e.target.value.trim();location.hash='#search';}});
document.addEventListener('change',async e=>{if(e.target.id==='theme-setting'){prefs.theme=e.target.value;localStorage.setItem('mm-theme',prefs.theme);applyTheme(prefs.theme);}if(e.target.id==='chat-attachment'&&e.target.files?.[0])toast(`Selected ${e.target.files[0].name}. It will upload when you send your message.`);});
window.addEventListener('hashchange',()=>{activeChat=location.hash.split('/')[1]||null;refresh().catch(e=>toast(e.message,'error'));});

async function boot(){
 try{
  let response;
  try{response=await fetch('/api/config');config=await readJson(response,'/api/config');}
  catch(err){console.warn('Firebase config endpoint is unavailable; guest demo remains available.',err);config={firebase:{}};}
  const c=config.firebase||{};firebaseConfigured=!!(c.apiKey&&c.projectId&&c.appId);
  if(!firebaseConfigured){authView('login');return;}
  fbApp=initializeApp(c);auth=getAuth(fbApp);db=getFirestore(fbApp);
  onAuthStateChanged(auth,async user=>{
   currentUser=user;guestMode=false;
   if(!user){me=null;cleanSubs();authView('login');return;}
   try{let bootData=await api('/bootstrap',{method:'POST',body:{}});if(bootData.refreshToken)await user.getIdToken(true);await loadProfile();await refresh();}
   catch(e){console.error(e);appRoot.innerHTML=`<main class="boot-screen"><div class="brand-mark">M+</div><h2>We could not load your account</h2><p>${esc(e.message)}</p><button class="btn" data-action="reload">Try again</button><button class="btn btn-ghost" data-action="start-guest">Explore guest demo</button></main>`;}
  });
 }catch(e){console.error(e);firebaseConfigured=false;authView('login');toast('Sign-in services could not be reached. Guest demo is still available.','error');}
}
boot();
